import { useMemo, useState } from 'react';
import {
  Card,
  Switch,
  Text,
  ThemeProvider,
  useTheme,
  useThemeType,
  type Theme,
  type ThemeType,
} from '@gravity-ui/uikit';

function ThemeToggle() {
  const theme = useTheme();
  const themeType = useThemeType();

  const handleUpdate = (checked: boolean) => {
    const nextTheme: Theme = checked ? 'dark' : 'light';
    const event = new CustomEvent('gravity:theme-change', { detail: nextTheme });
    window.dispatchEvent(event);
  };

  return (
    <Switch
      checked={themeType === 'dark'}
      onUpdate={handleUpdate}
      content=\"Тёмная тема\"
      aria-label=\"Тёмная тема\"
    />
  );
}

export function App() {
  const [theme, setTheme] = useState<Theme>('light');

  const isDark = theme === 'dark';
  const themeType: ThemeType = isDark ? 'dark' : 'light';

  const background = themeType === 'dark' ? '#17171a' : '#ffffff';
  const heading = themeType === 'dark' ? 'var(--g-color-text-primary)' : 'var(--g-color-text-primary)';

  useMemo(() => {
    const handleThemeChange = (event: Event) => {
      const nextTheme = (event as CustomEvent<Theme>).detail;
      setTheme(nextTheme === 'dark' ? 'dark' : 'light');
    };

    window.addEventListener('gravity:theme-change', handleThemeChange);
    return () => window.removeEventListener('gravity:theme-change', handleThemeChange);
  }, []);

  return (
    <ThemeProvider theme={theme}>
      <div
        style={{
          minHeight: '100vh',
          background,
          padding: 24,
          transition: 'background-color 200ms ease',
        }}
      >
        <Card style={{ maxWidth: 560, padding: 24 }} theme=\"normal\">
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 16,
              marginBottom: 16,
            }}
          >
            <div>
              <Text variant=\"header-1\" as=\"h1\" style={{ color: heading }}>
                Настройки интерфейса
              </Text>
              <Text variant=\"body-1\" color=\"secondary\">
                Выберите тему оформления
              </Text>
            </div>
            <ThemeToggle />
          </div>
          <Text variant=\"body-2\" color=\"secondary\">
            Сейчас используется {themeType === 'dark' ? 'тёмная' : 'светлая'} тема.
          </Text>
        </Card>
      </div>
    </ThemeProvider>
  );
}
EOF
